package cl.felipe.agrofrost.application.usecase;
import cl.felipe.agrofrost.domain.entity.Field; import cl.felipe.agrofrost.domain.exception.DuplicateFieldException; import cl.felipe.agrofrost.domain.repository.FieldRepository; import cl.felipe.agrofrost.domain.valueobject.*; import org.junit.jupiter.api.Test; import org.mockito.*; import java.util.Optional; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class RegisterFieldUseCaseTest { @Mock FieldRepository repository; @InjectMocks RegisterFieldUseCase useCase; RegisterFieldUseCaseTest() { MockitoAnnotations.openMocks(this); } private Field field() { return new Field(new FieldId("f-1"),new FieldName("North"),new Crop("Grapes"),new CriticalTemperature(0)); } @Test void registersAfterSearchingById() { Field field=field(); when(repository.findById(field.id())).thenReturn(Optional.empty()); useCase.execute(field); verify(repository).findById(field.id()); verify(repository).save(field); } @Test void rejectsDuplicateWithoutSaving() { Field field=field(); when(repository.findById(field.id())).thenReturn(Optional.of(field)); assertThrows(DuplicateFieldException.class, () -> useCase.execute(field)); verify(repository, never()).save(any()); } @Test void rejectsNullDependencyAndField() { assertThrows(NullPointerException.class, () -> new RegisterFieldUseCase(null)); assertThrows(NullPointerException.class, () -> useCase.execute(null)); } }
